code_after:
✅ Correct pattern — enforce msg.sender as owner
contract SafeClaimTokens {
    function claimTokens(
        address token,
        uint256 amount,
        address recipient
    ) external {
        //

✅ owner is always the caller themselves
        IERC20(token).transferFrom(msg.sender, recipient, amount);
    }
}

